const result = $input.first().json;
const context = $('Prepare Async Context').first().json.context;
const processingTime = Date.now() - context.start_time;

let isSuccess = false;
let quizData = null;
let errorInfo = null;

try {
  const content = result.choices?.[0]?.message?.content || '{}';
  quizData = JSON.parse(content);
  isSuccess = !result.error && quizData;
} catch (e) {
  isSuccess = false;
  errorInfo = {
    code: 'PARSE_ERROR',
    message: 'Failed to parse quiz response: ' + e.message
  };
}

let callback;

if (isSuccess) {
  callback = {
    job_id: context.job_id,
    conversation_id: context.conversation_id,
    user_id: context.user_id,
    guild_id: context.guild_id,
    channel_id: context.channel_id,
    success: true,
    result: {
      quiz: quizData,
      output_type: 'quiz',
      model: result.model || context.model
    },
    metrics: {
      tokens_used: result.usage?.total_tokens || 0,
      prompt_tokens: result.usage?.prompt_tokens || 0,
      completion_tokens: result.usage?.completion_tokens || 0,
      processing_time_ms: processingTime
    },
    error: null
  };
} else {
  const errorCode = errorInfo?.code || result.error?.code || 'INTERNAL_ERROR';
  const errorMessage = errorInfo?.message || result.error?.message || 'Quiz generation failed';

  callback = {
    job_id: context.job_id,
    conversation_id: context.conversation_id,
    user_id: context.user_id,
    guild_id: context.guild_id,
    channel_id: context.channel_id,
    success: false,
    result: null,
    metrics: {
      tokens_used: 0,
      processing_time_ms: processingTime
    },
    error: {
      code: errorCode,
      message: errorMessage,
      retriable: ['rate_limit_exceeded', 'timeout', 'server_error'].includes(errorCode)
    }
  };
}

// RFC-040: Generate HMAC signature
const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET || 'default-secret';
const payload = JSON.stringify(callback);
const signature = crypto.createHmac('sha256', secret).update(payload).digest('hex');

return {
  json: {
    callback: callback,
    callback_url: context.callback_url,
    signature: signature,
    payload: payload
  }
};

const result = $input.first().json;
const context = $('Prepare Sync Context').first().json.context;
const processingTime = Date.now() - context.start_time;

try {
  const content = result.choices?.[0]?.message?.content || '{}';
  const parsed = JSON.parse(content);

  return {
    json: {
      success: true,
      data: parsed,
      meta: {
        provider: 'openai',
        model: result.model || context.model,
        execution_mode: context.execution_mode,
        tokens_used: result.usage?.total_tokens || 0,
        processing_time_ms: processingTime
      }
    }
  };
} catch (e) {
  return {
    json: {
      success: false,
      error: {
        code: 500,
        message: 'Failed to parse quiz response: ' + e.message,
        status: 'INTERNAL_ERROR'
      },
      meta: {
        provider: 'openai',
        execution_mode: context.execution_mode,
        processing_time_ms: processingTime
      }
    }
  };
}
